import {QUESTIONS} from './questions.js';
import {AXES,GLOSSARY,TIMELINE,FAQ} from './context.js';
import {PARTIES,FIGURES} from './politics.js';
import {VERSIONS,questionSet,validAnswer,scoreProfile,isComplete,rankProfiles,restoreState} from './core.js';
import {drawRadar} from './hero.js';
import {PHOTOS} from './photos.js';
const app=document.querySelector('#app'),homeHTML=app.innerHTML,KEY='uruguay-compass-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
let state=null,storageOK=true,theme='light',selectedVersion='short';
try{state=restoreState(localStorage.getItem(KEY),QUESTIONS);theme=localStorage.getItem('compass-theme')==='dark'?'dark':'light'}catch{storageOK=false}
document.documentElement.dataset.theme=theme;
const announce=t=>{document.querySelector('#announcement').textContent=t};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false;announce('No se pudo guardar. Podés seguir, pero el avance se pierde al cerrar.')}}
function go(route){if(location.hash===`#${route}`)render();else location.hash=route}
function profile(){return state&&isComplete(questionSet(QUESTIONS,state.version),state.answers)?scoreProfile(questionSet(QUESTIONS,state.version),state.answers):null}
const sourceList=s=>`<ul class="sources">${(s||[]).map(x=>`<li>${link(x.url,x.title)}</li>`).join('')}</ul>`;
function portrait(e){const p=PHOTOS[e.id];return p?`<figure class="portrait"><img src="${esc(p.src)}" alt="Retrato de ${esc(e.name)}" width="200" height="240" loading="lazy"><figcaption>${link(p.source,`${p.author} · ${p.license}`)}</figcaption></figure>`:''}
const secondary=(a,t)=>`<button class="secondary" data-action="${a}">${t}</button>`;
function header(){return `<header class="app-header"><a class="app-brand" href="#inicio"><img src="sun.svg" width="36" height="36" alt=""><strong>Uruguay Compass</strong></a><nav aria-label="Principal"><a href="#enciclopedia">Enciclopedia</a><a href="#metodologia">Metodología</a><a href="#faq">Ayuda</a><button class="text-button" data-action="theme" aria-label="${theme==='dark'?'Activar modo claro':'Activar modo oscuro'}">${theme==='dark'?'Modo claro':'Modo oscuro'}</button></nav></header>`}
function shell(title,body,wide=false){app.innerHTML=header()+`<main id="main" class="page ${wide?'wide':''}" tabindex="-1"><h1>${title}</h1>${body}</main><footer class="app-footer"><span>Educativo. Sin validación científica ni recomendación de voto.</span><a href="#correcciones">Señalar un error</a><a href="#privacidad">Privacidad</a></footer>`}
function renderHome(){app.innerHTML=homeHTML;app.querySelector('#home-title').innerHTML='¿A qué personaje político<br class="desktop-br"> se acercan <span>tus ideas?</span>';const chosen=app.querySelector(`[name="version"][value="${selectedVersion}"]`);if(chosen)chosen.checked=true;const footer=app.querySelector('.home-footer');footer.insertAdjacentHTML('beforeend',`<div class="home-tools"><a href="#faq">Ayuda</a><a href="#correcciones">Señalar un error</a><button class="text-button" data-action="theme">${theme==='dark'?'Modo claro':'Modo oscuro'}</button></div>`);if(state)app.querySelector('.home-intro').insertAdjacentHTML('beforeend',`<div class="resume-actions"><a href="#${state.completed?'resultados':'test'}">${state.completed?'Ver mi resultado guardado':'Continuar mi test'}</a>${secondary('reset','Empezar de nuevo')}</div>`);drawRadar(document.querySelector('#home-radar'),[70,48,58,54,44,56,68,75,57,72,63,48]);}
const answerLabels=['Muy en desacuerdo','En desacuerdo','Ni de acuerdo ni en desacuerdo','De acuerdo','Muy de acuerdo'];
function testScreen(){if(!state){go('inicio');return}if(state.completed){go('resultados');return}const qs=questionSet(QUESTIONS,state.version),q=qs[state.cursor],v=state.answers[q.id];shell('Tus ideas, pregunta a pregunta',`<div class="test-top"><span>${VERSIONS[state.version].label} · Pregunta ${state.cursor+1} de ${qs.length}</span><span>${Object.keys(state.answers).length} respondidas</span></div><progress value="${Object.keys(state.answers).length}" max="${qs.length}" aria-label="Preguntas respondidas"></progress><form id="question-form"><fieldset><legend class="question">${esc(q.text)}</legend><div class="answers">${answerLabels.map((label,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" ${v===i?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><div class="test-controls"><button type="button" class="secondary" data-action="previous" ${state.cursor===0?'disabled':''}>Anterior</button><button class="primary" type="submit" ${!validAnswer(v)?'disabled':''}>${state.cursor===qs.length-1?'Ver mi resultado':'Siguiente'}</button></div></form><p class="small muted">${storageOK?'Tu avance se guarda solo en este navegador.':'El almacenamiento está bloqueado. Podés seguir, pero no cerrar esta página.'} Podés volver y cambiar cualquier respuesta.</p><details><summary>¿Qué significa este tema?</summary><p>${esc(AXES[q.axis].description)}</p><a href="#eje/${q.axis}">Leer ambas posturas y volver al test</a></details><a class="quiet-link" href="#inicio">Salir y conservar avance</a>`);}
function axisBars(p){return AXES.map((a,i)=>`<details class="axis-result"><summary><span>${esc(a.name)}</span><strong>${p[i]} / 100</strong></summary><div class="pole-labels"><span>${esc(a.left)} · ${100-p[i]}%</span><span>${esc(a.right)} · ${p[i]}%</span></div><div class="axis-track"><span style="left:${p[i]}%"></span></div><p>${esc(a.description)}</p><p class="small">El puntaje expresa orientación entre polos, no cuánto sabés ni cuán firme es tu opinión.</p><a href="#eje/${i}">Entender este eje</a></details>`).join('')}
const ranked=()=>rankProfiles(profile(),FIGURES.filter(f=>f.rankEligible));
function resultScreen(){const p=profile();if(!p){shell('Todavía falta tu perfil',`<p>Completá las preguntas para ver tus doce posiciones.</p><a class="primary button-link" href="#${state?'test':'inicio'}">${state?'Continuar':'Elegir un test'}</a>`);return}const r=ranked(),top=r.ranked.slice(0,3),far=r.ranked.at(-1),ties=new Set(r.ranked.map(x=>x.score)).size<r.ranked.length;shell('Tus ideas, en doce ejes',`<p class="lead">En estas respuestas, tu perfil se acerca más al de <strong>${esc(top[0]?.entity.name)}</strong>, usando el programa que representó en 2024.</p><p>Parecerse en estos ejes no significa pensar igual en todo ni apoyar a un partido.</p><section><h2>Coincidencias con personajes</h2><p class="notice">Esta edición compara seis candidaturas de 2024, una por partido. La afinidad usa los mismos ${r.axes.length} ejes con evidencia común: ${r.axes.map(i=>AXES[i].short).join(', ')}. Las figuras históricas están en la enciclopedia y no se incluyen en este ranking.</p>${top.map(x=>matchRow(x)).join('')}<h3>La referencia más lejana</h3>${matchRow(far)}${ties?'<p class="small">Hay porcentajes empatados; dentro de cada empate, el orden es alfabético y no expresa mayor afinidad.</p>':''}<a href="#comparaciones">Ver las seis candidaturas y los partidos</a></section><section class="result-overview"><div><h2>Tu mapa</h2><canvas id="result-radar" width="800" height="800" aria-label="Tu perfil en doce ejes, detallado en la lista siguiente"></canvas><p class="small">Los ejes se leen en el orden de la lista, desde arriba y en sentido horario. Un área mayor no es un resultado mejor.</p></div><div><h2>Tu posición en cada eje</h2>${axisBars(p)}</div></section><section><h2>Guardá tu resultado</h2><p>La imagen se crea en tu navegador. Solo se comparte si elegís hacerlo.</p><div class="actions">${secondary('download','Guardar imagen PNG')}${secondary('share','Compartir imagen')}${secondary('reset','Repetir el test')}<a href="#privacidad">Borrar mis datos</a></div><p id="export-status" role="status"></p><canvas id="share-preview" class="share-preview" width="1200" height="1500" hidden aria-label="Vista previa de la tarjeta"></canvas></section>`,true);drawRadar(document.querySelector('#result-radar'),p);}
function matchRow(x){if(!x)return '';const e=x.entity;return `<article class="match-row">${portrait(e)}<div class="match-copy"><h3><a href="#${e.id.startsWith('partido-')?'partido/'+e.id.slice(8):'ficha/'+e.id}">${esc(e.name)}</a></h3><p class="small">${esc(e.partyName||e.period||'')} · ${esc(e.era||'')}</p><p>${esc(e.summary)}</p><a href="#comparar/${e.id}">Comparar eje por eje y ver fuentes</a></div><strong class="match-score">${x.score}%<span>coincidencia editorial</span></strong></article>`}
function compareScreen(id){const p=profile(),e=[...FIGURES,...PARTIES.map(x=>({...x,id:'partido-'+x.id}))].find(x=>x.id===id);if(!p||!e){shell('Comparación no disponible','<p>Necesitás completar el test y elegir una ficha válida.</p><a href="#resultados">Ir a resultados</a>');return}const common=ranked().axes;shell(`Tus respuestas y ${esc(e.name)}`,`<p>${esc(e.comparisonNote)}</p><p class="notice">Puntajes editoriales de 0 (polo izquierdo) a 100 (derecho). «Sin evidencia» no equivale a 50. Solo los ejes marcados como comunes intervienen en el ranking.</p><div class="table-scroll"><table><caption>Comparación por eje</caption><thead><tr><th>Eje y polos</th><th>Vos</th><th>Referencia</th><th>Fundamento y fuente</th></tr></thead><tbody>${AXES.map((a,i)=>{const ev=e.evidence?.find(v=>v.axis===i),s=ev&&e.sources[ev.source];return `<tr><th>${esc(a.name)}${common.includes(i)?'<small>Común al ranking</small>':''}<small>${esc(a.left)} → ${esc(a.right)}</small></th><td>${p[i]}</td><td>${e.profile[i]===null?'Sin evidencia':e.profile[i]}</td><td>${esc(e.rationale[i])}${s?`<br>${link(s.url,`${s.title}${ev.page?' · p. '+ev.page:''}`)}`:''}</td></tr>`}).join('')}</tbody></table></div><a href="#resultados">Volver a mi resultado</a>`,true)}
function comparisons(){const p=profile();if(!p){go('resultados');return}const a=ranked(),b=rankProfiles(p,PARTIES.map(x=>({...x,id:'partido-'+x.id})));shell('Todas las comparaciones',`<p>Las candidaturas y los partidos pueden coincidir en porcentaje porque se usa el mismo programa como referencia. No es una estimación independiente de cada persona.</p><h2>Candidaturas de 2024</h2>${a.ranked.map(matchRow).join('')}<h2>Partidos con representación parlamentaria</h2><p class="small">Referencia: programas 2025–2030 y composición parlamentaria al inicio de la legislatura. Fuentes en cada ficha.</p>${b.ranked.map(matchRow).join('')}<a href="#resultados">Volver al resultado</a>`,true)}
function encyclopedia(){shell('Entender la política uruguaya',`<p class="lead">Doce temas, varias posturas. Explorá los debates, las figuras y las palabras detrás del test.</p><nav class="section-nav" aria-label="Secciones de la enciclopedia"><a href="#figuras">Personajes</a><a href="#partidos">Partidos</a><a href="#glosario">Glosario</a><a href="#historia">Historia</a></nav><h2>Los doce ejes</h2><div class="reading-list">${AXES.map(a=>`<a href="#eje/${a.id}"><strong>${esc(a.name)}</strong><span>${esc(a.left)} ↔ ${esc(a.right)}</span></a>`).join('')}</div>`)}
function axisScreen(id){const a=AXES[Number(id)];if(!a){notFound();return}shell(esc(a.name),`<p class="lead">${esc(a.description)}</p><div class="two-poles"><section><h2>${esc(a.left)}</h2><p>${esc(a.leftText)}</p></section><section><h2>${esc(a.right)}</h2><p>${esc(a.rightText)}</p></section></div><h2>Debates en Uruguay</h2><ul>${a.debates.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Para consultar</h2>${sourceList(a.sources)}<div class="actions"><a href="#enciclopedia">Todos los ejes</a>${state&&!state.completed?'<a href="#test">Volver a mi pregunta</a>':''}</div>`)}
function entityList(kind){const es=kind==='partidos'?PARTIES:FIGURES;shell(kind==='partidos'?'Partidos y sus propuestas':'Personajes de distintas épocas',`<p>Las fichas presentan el contexto y las fuentes. Una ubicación editorial no resume una trayectoria completa.</p><label class="search-label">Buscar por nombre<input type="search" id="entity-search" placeholder="Escribí un nombre" autocomplete="off"></label><div class="reading-list" id="entity-list">${es.map(e=>`<a data-search="${esc((e.name+' '+(e.partyName||'')).toLocaleLowerCase('es'))}" href="#${kind==='partidos'?'partido':'ficha'}/${e.id}"><strong>${esc(e.name)}</strong><span>${esc(e.era||e.period)} · ${esc(e.partyName||e.short||'')}</span></a>`).join('')}</div><p id="search-empty" hidden>No hay coincidencias. Probá con otra palabra.</p>`)}
function entityScreen(id,party=false){const e=(party?PARTIES:FIGURES).find(x=>x.id===id);if(!e){notFound();return}shell(esc(e.name),`${portrait(e)}<p class="muted">${esc(e.era||e.period)} · ${esc(e.partyName||e.short||'')}</p><p class="lead">${esc(e.bio||e.summary)}</p>${e.actions?.length?`<h2>Trayectoria y propuestas documentadas</h2><ul>${e.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="notice">${esc(e.comparisonNote)} Las posturas pueden cambiar con el tiempo. Los números siguientes son estimaciones editoriales.</p><h2>Ubicación y fundamentos</h2>${AXES.map((a,i)=>`<details><summary>${esc(a.name)} <span>${e.profile[i]===null?'Sin evidencia suficiente':e.profile[i]+' / 100'}</span></summary><p>${esc(a.left)} → ${esc(a.right)}</p><p>${esc(e.rationale[i])}</p>${(e.evidence||[]).filter(v=>v.axis===i).map(v=>{const s=e.sources[v.source];return `<p>${s?link(s.url,`${s.title}${v.page?' · p. '+v.page:''}`):''}</p>`}).join('')}</details>`).join('')}<h2>Fuentes públicas</h2>${sourceList(e.sources)}<div class="actions">${profile()?`<a href="#comparar/${party?'partido-':''}${e.id}">Comparar con mis respuestas</a>`:''}<a href="#correcciones">Proponer una corrección con fuentes</a><a href="#${party?'partidos':'figuras'}">Volver al índice</a></div>`)}
function glossary(){shell('Glosario',`<p>Palabras políticas en contexto uruguayo, sin convertirlas en etiquetas para personas.</p><label class="search-label">Buscar un término<input id="glossary-search" type="search" placeholder="Por ejemplo, liberal o AFAP"></label><div id="glossary-list">${GLOSSARY.map(x=>`<article class="glossary-entry" data-search="${esc((x.term+' '+x.definition).toLocaleLowerCase('es'))}"><h2>${esc(x.term)}</h2><p>${esc(x.definition)}</p></article>`).join('')}</div><p id="search-empty" hidden>No encontramos ese término. Probá con otra palabra.</p>`)}
function history(){shell('Un recorrido por la historia política',`<p>Una selección de hitos para ubicar los debates en su época; no pretende agotar la historia del país.</p><ol class="timeline">${TIMELINE.map(t=>`<li><time>${esc(t.year)}</time><div><h2>${esc(t.title)}</h2><p>${esc(t.text)}</p>${link(t.source.url,t.source.title)}</div></li>`).join('')}</ol>`)}
function methodology(){shell('Cómo funciona este test',`<p class="lead">Tus respuestas forman un perfil. Las decisiones editoriales que lo construyen están a la vista.</p><h2>Preguntas y versiones</h2><p>El banco contiene 240 afirmaciones originales, 20 por eje, con una idea principal cada una. Se alternan propuestas orientadas a ambos polos. La Corta usa las primeras 3 de cada eje; la Completa, 5; la Extrema, 20. Las versiones largas profundizan, no cambian los temas.</p><h2>Del acuerdo al puntaje</h2><p>Las cinco opciones valen −2, −1, 0, 1 y 2. Si la afirmación apunta al polo izquierdo, se invierte su signo. En cada eje se calcula la media y se transforma con <strong>50 + 25 × media</strong>. Así, 0 corresponde al polo izquierdo, 100 al derecho y 50 al centro. Se redondea al entero más cercano. Todas las preguntas de un eje pesan igual y ningún eje reemplaza a los demás.</p><h2>Comparación con figuras y partidos</h2><p>La afinidad es <strong>100 − promedio de las diferencias absolutas</strong> entre tus puntajes y los de referencia. Es un índice de proximidad, no una probabilidad. Los empates se ordenan alfabéticamente.</p><p>Esta edición incluye seis candidaturas de 2024, una por cada partido parlamentario, con el programa que representaron. La fuente es programática: no prueba que cada punto fuera una convicción personal. Los puntajes son juicios editoriales orientativos, no números publicados por esas personas.</p><p>Para comparar con la misma cobertura, el ranking usa cinco ejes documentados en todos los programas: economía, seguridad y libertades, comercio exterior, educación y seguridad social, ambiente y desarrollo. Se muestran también las demás ubicaciones disponibles; no entran en ese índice. Las figuras y los partidos pueden obtener el mismo porcentaje porque comparten la referencia programática.</p><h2>Historia y vacíos de evidencia</h2><p>Las 16 figuras tienen fichas, pero las históricas quedan fuera del ranking de candidaturas. No se presume qué habrían pensado sobre instituciones o debates posteriores. Los campos sin base suficiente quedan sin puntaje: no se completan con 50.</p><h2>Qué no puede decirte</h2><p>No mide tu identidad, cuánto sabés ni a quién deberías votar. No está validado científicamente. Una respuesta neutra puede reflejar equilibrio, dudas o falta de información; el test no distingue esos motivos. El promedio puede esconder desacuerdos dentro de un eje, especialmente en educación/seguridad social y memoria/Fuerzas Armadas.</p><p>Las fuentes pueden tener sesgos y los programas no equivalen a todas las políticas efectivamente implementadas. La selección de temas, orientación y cifras merece revisión pública. Referencias recopiladas para esta edición: noviembre de 2026; los programas corresponden a 2024.</p><div class="actions"><a href="#correcciones">Cuestionar una pregunta o ubicación</a><a href="#faq">Preguntas frecuentes</a></div>`)}
function faq(){shell('Preguntas frecuentes',FAQ.map((f,i)=>`<details><summary>${esc(f.q)}</summary><p>${esc(i===FAQ.length-1?'Usá «Señalar un error» para preparar una observación con una fuente pública. Podés descargarla o abrir un borrador de Issue en GitHub. Solo se envía cuando vos lo publicás allí; GitHub puede pedir una cuenta.':f.a)}</p></details>`).join(''))}
function privacy(){shell('Tus respuestas quedan acá',`<p>El test procesa todo en tu navegador. No incluye analytics, cuentas propias ni llamadas para enviar tus respuestas. El servidor de alojamiento recibe las solicitudes normales de archivos, no tus elecciones del test.</p><p>El progreso se guarda en este navegador. Otras personas que usen el mismo perfil podrían verlo. El modo privado o las preferencias de almacenamiento pueden impedir que se conserve.</p><p>Las fuentes públicas y GitHub son servicios externos. Se abren solo cuando elegís sus enlaces. Los borradores de correcciones contienen únicamente lo que escribas en el formulario, nunca las respuestas del test.</p><h2>Borrar el avance y resultado</h2><p>Esta acción borra el estado del test guardado en este navegador.</p>${secondary('erase','Borrar mis respuestas')}<p id="erase-status" role="status"></p>`)}
function corrections(){shell('Ayudanos a corregir',`<p>Señalá un error o cuestioná una ubicación con fuentes. No incluyas datos personales ni tus respuestas del test.</p><form id="correction-form"><label>Pregunta, eje o personaje<input name="subject" required maxlength="160" placeholder="Por ejemplo: economía, pregunta sobre ANCAP"></label><label>Qué proponés corregir<textarea name="message" required minlength="15" maxlength="5000" rows="6"></textarea></label><label>Fuente pública (enlace HTTPS)<input name="source" type="url" pattern="https://.*" required maxlength="1500" placeholder="https://"></label><div class="actions"><button class="primary" type="submit">Preparar reporte</button></div></form><div id="correction-output" hidden><h2>Reporte preparado</h2><p>No se envió todavía. Revisalo y elegí si querés publicarlo en GitHub; puede requerir una cuenta.</p><pre id="correction-preview"></pre><div class="actions"><a id="issue-link" target="_blank" rel="noopener noreferrer">Abrir borrador en GitHub</a>${secondary('report-download','Descargar reporte TXT')}</div></div>`)}
function notFound(){shell('No encontramos esa página','<p>Volvé al inicio o explorá la enciclopedia.</p><a href="#inicio">Ir al inicio</a>')}
function render(){const [route,id]=location.hash.slice(1).split('/');const views={inicio:renderHome,test:testScreen,resultados:resultScreen,comparaciones:comparisons,enciclopedia:encyclopedia,figuras:()=>entityList('figuras'),partidos:()=>entityList('partidos'),eje:()=>axisScreen(id),ficha:()=>entityScreen(id),partido:()=>entityScreen(id,true),comparar:()=>compareScreen(id),glosario:glossary,historia:history,metodologia:methodology,faq,privacidad:privacy,correcciones:corrections};(Object.hasOwn(views,route||'inicio')?views[route||'inicio']:notFound)();document.title=`${document.querySelector('h1')?.textContent||'Inicio'} · Uruguay Compass`;window.scrollTo(0,0);if(route&&route!=='inicio')document.querySelector('#main')?.focus({preventScroll:true})}
let reportText='';
document.addEventListener('click',async event=>{if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main')?.focus();return}const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='start'){selectedVersion=app.querySelector('[name="version"]:checked')?.value||selectedVersion;if(state){go(state.completed?'resultados':'test');return}state={schema:1,version:selectedVersion,answers:{},cursor:0,completed:false};save();go('test')}
else if(action==='previous'){state.cursor=Math.max(0,state.cursor-1);save();testScreen();document.querySelector('#main')?.focus({preventScroll:true});announce(`Pregunta ${state.cursor+1} de ${questionSet(QUESTIONS,state.version).length}`)}
else if(action==='theme'){theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('compass-theme',theme)}catch{}b.textContent=theme==='dark'?'Modo claro':'Modo oscuro';b.setAttribute('aria-label',`Activar ${b.textContent.toLowerCase()}`)}
else if(action==='reset'){shell('¿Empezar otro test?',`<p>Tu resultado o avance actual se reemplazará cuando empieces de nuevo. También podés guardar su imagen primero.</p><div class="actions">${secondary('confirm-reset','Sí, empezar de nuevo')}<a href="#${state?.completed?'resultados':'test'}">Conservar mi test</a></div>`)}
else if(action==='confirm-reset'){state=null;try{localStorage.removeItem(KEY)}catch{}go('inicio')}
else if(action==='erase'){state=null;try{localStorage.removeItem(KEY);document.querySelector('#erase-status').textContent='Respuestas y resultado borrados.'}catch{document.querySelector('#erase-status').textContent='El navegador impidió borrar el almacenamiento. Borrá los datos de este sitio en la configuración del navegador. El perfil ya no se muestra en esta sesión.'}}
else if(action==='download'||action==='share'){try{b.disabled=true;const blob=await resultImage();if(action==='share'&&navigator.canShare?.({files:[new File([blob],'uruguay-compass.png',{type:'image/png'})]})){await navigator.share({files:[new File([blob],'uruguay-compass.png',{type:'image/png'})],title:'Mi perfil · Uruguay Compass'})}else{download(blob,'uruguay-compass.png');document.querySelector('#export-status').textContent=action==='share'?'Este navegador no permite compartir archivos directamente. Descargamos la imagen para que la compartas.':'Imagen guardada. La tarjeta incluye el alcance y los límites de la comparación.'}}catch(e){if(e.name!=='AbortError')document.querySelector('#export-status').textContent='No se pudo crear la imagen. Intentá de nuevo desde un navegador actualizado.'}finally{b.disabled=false}}
else if(action==='report-download')download(new Blob([reportText],{type:'text/plain;charset=utf-8'}),'correccion-compass.txt')});
document.addEventListener('change',event=>{if(event.target.name==='answer'&&state){const q=questionSet(QUESTIONS,state.version)[state.cursor];state.answers[q.id]=Number(event.target.value);save();document.querySelector('#question-form button[type="submit"]').disabled=false}if(event.target.name==='version')selectedVersion=event.target.value});
document.addEventListener('submit',event=>{if(event.target.id==='question-form'){event.preventDefault();const qs=questionSet(QUESTIONS,state.version);if(!validAnswer(state.answers[qs[state.cursor].id]))return;if(state.cursor===qs.length-1){if(!isComplete(qs,state.answers)){state.cursor=qs.findIndex(q=>!validAnswer(state.answers[q.id]));save();testScreen();return}state.completed=true;save();go('resultados')}else{state.cursor++;save();testScreen();document.querySelector('#main').focus({preventScroll:true});announce(`Pregunta ${state.cursor+1} de ${qs.length}`)}}if(event.target.id==='correction-form'){event.preventDefault();const fd=new FormData(event.target),subject=String(fd.get('subject')),message=String(fd.get('message')),source=String(fd.get('source'));reportText=`Ficha o pregunta: ${subject}\n\nCorrección propuesta:\n${message}\n\nFuente:\n${source}\n`;document.querySelector('#correction-preview').textContent=reportText;document.querySelector('#issue-link').href=`https://github.com/faacuaramburu/EspectroUruguayo/issues/new?title=${encodeURIComponent('Corrección: '+subject)}&body=${encodeURIComponent(reportText)}`;document.querySelector('#correction-output').hidden=false;document.querySelector('#correction-output').scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
document.addEventListener('input',event=>{if(!['entity-search','glossary-search'].includes(event.target.id))return;const needle=event.target.value.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'');let count=0;for(const row of document.querySelectorAll('[data-search]')){const match=row.dataset.search.normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(needle);row.hidden=!match;if(match)count++}document.querySelector('#search-empty').hidden=count>0});
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function resultImage(){await document.fonts.ready;const canvas=document.querySelector('#share-preview');canvas.hidden=false;const c=canvas.getContext('2d'),p=profile(),r=ranked(),top=r.ranked[0];c.fillStyle='#ffffff';c.fillRect(0,0,1200,1500);c.fillStyle='#0c1939';c.font='700 40px Biryani';c.fillText('Uruguay Compass — Los 12 Ejes',65,90);c.font='400 26px Biryani';c.fillText('En estas respuestas, mi perfil se acerca más al de',65,155);c.font='700 46px Biryani';c.fillText(top.entity.name,65,230);c.font='400 25px Biryani';c.fillText(`${top.score}% de coincidencia editorial · Programa de candidatura 2024`,65,280);p.forEach((n,i)=>{const y=345+i*75;c.fillStyle='#0c1939';c.font='700 21px Biryani';c.fillText(AXES[i].short,65,y);c.font='400 17px Biryani';c.fillText(AXES[i].left,65,y+25);c.textAlign='right';c.fillText(AXES[i].right,1135,y+25);c.fillText(`${n}/100`,1135,y);c.textAlign='left';c.fillStyle='#dce9fa';c.fillRect(370,y+10,450,8);c.fillStyle='#0857e9';c.fillRect(370+n*4.5-4,y+4,8,20)});c.fillStyle='#0c1939';c.font='400 22px Biryani';['Afinidad calculada sobre 5 ejes comunes, no los doce.','No implica pensar igual en todo ni apoyar a un partido.','Educativo. Sin validación científica ni recomendación de voto.'].forEach((t,i)=>c.fillText(t,65,1320+i*45));return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('PNG no disponible')),'image/png'))}
window.addEventListener('hashchange',render);render();
